import math

def clipValue(value, upper_limit, lower_limit):
    """
    Clips the given value within the specified range [lower_limit, upper_limit].
    If any of the inputs are NaN, returns NaN.

    :param value: The value to be clipped.
    :param upper_limit: The upper boundary of the clipping range.
    :param lower_limit: The lower boundary of the clipping range.
    :return: The clipped value or NaN if any input is NaN.
    """
    if math.isnan(value) or math.isnan(upper_limit) or math.isnan(lower_limit):
        return float('nan')
    else:
        return max(lower_limit, min(value, upper_limit))
