import threading

class Node:
    def __init__(self, value, prev=None, next_=None):
        self.value = value
        self.prev = prev
        self.next = next_

class ThreadSafeDeque:
    def __init__(self):
        self.head = None
        self.tail = None
        self.length = 0
        self.lock = threading.Lock()

    def append(self, value):
        """
        Adds an element to the right end of the deque.
        """
        with self.lock:
            new_node = Node(value, prev=self.tail)
            if self.tail is not None:
                self.tail.next = new_node
            self.tail = new_node
            if self.head is None:
                self.head = new_node
            self.length += 1

    def pop(self):
        """
        Removes and returns an element from the right end of the deque.
        Raises IndexError if the deque is empty.
        """
        with self.lock:
            if self.tail is None:
                raise IndexError("pop from an empty deque")
            popped_node = self.tail
            self.tail = popped_node.prev
            if self.tail is not None:
                self.tail.next = None
            if self.tail is None:
                self.head = None
            self.length -= 1
            return popped_node.value

    def popleft(self):
        """
        Removes and returns an element from the left end of the deque.
        Raises IndexError if the deque is empty.
        """
        with self.lock:
            if self.head is None:
                raise IndexError("pop from an empty deque")
            popped_node = self.head
            self.head = popped_node.next
            if self.head is not None:
                self.head.prev = None
            if self.head is None:
                self.tail = None
            self.length -= 1
            return popped_node.value

    def appendleft(self, value):
        """
        Adds an element to the left end of the deque.
        """
        with self.lock:
            new_node = Node(value, next_=self.head)
            if self.head is not None:
                self.head.prev = new_node
            self.head = new_node
            if self.tail is None:
                self.tail = new_node
            self.length += 1

    def __len__(self):
        """
        Returns the number of elements in the deque.
        """
        return self.length

# Testing the implementation
if __name__ == "__main__":
    def consumer(dq):
        for _ in range(5):
            try:
                print(f"Popped from right: {dq.pop()}")
            except IndexError:
                break
        for _ in range(5):
            try:
                print(f"Popped from left: {dq.popleft()}")
            except IndexError:
                break

    def producer(dq):
        for i in range(5):
            dq.append(i)
            dq.appendleft(-i)

    dq = ThreadSafeDeque()
    threads = []

    for _ in range(3):
        t = threading.Thread(target=producer, args=(dq,))
        threads.append(t)
        t.start()

    for _ in range(3):
        t = threading.Thread(target=consumer, args=(dq,))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()
    print("Final deque length:", len(dq))
