import json

def json_parser(json_str):
    """
    Parses a JSON string containing nested student data and computes the average grades for each student.

    :param json_str: A JSON string representing an array of student objects.
    :return: A dictionary with student names as keys and tuples (age, average_grade) as values.
    """
    def find_grades(data):
        """
        Recursively finds all 'grades' lists in the nested data structure.

        :param data: The data structure to search through.
        :yield: Lists of grades found in the data.
        """
        if isinstance(data, dict):
            if 'grades' in data:
                yield data['grades']
            for value in data.values():
                yield from find_grades(value)
        elif isinstance(data, list):
            for item in data:
                yield from find_grades(item)

    def calculate_average(grades_list):
        """
        Calculates the average of a list of grades.

        :param grades_list: A list of integers representing grades.
        :return: The average of the grades, or 0 if the list is empty.
        """
        if not grades_list:
            return 0
        return sum(grades_list) / len(grades_list)

    parsed_data = json.loads(json_str)
    result = {}

    for student in parsed_data:
        name = student.get('name')
        age = student.get('age')
        all_grades = []

        for grades in find_grades(student):
            all_grades.extend(grades)

        average_grade = calculate_average(all_grades)
        result[name] = (age, average_grade)

    return result
