class MinHeap:
    def __init__(self):
        """Initialize an empty min-heap."""
        self.heap = []

    def parent(self, index):
        """Return the parent index of the given index."""
        return (index - 1) // 2

    def left_child(self, index):
        """Return the left child index of the given index."""
        return 2 * index + 1

    def right_child(self, index):
        """Return the right child index of the given index."""
        return 2 * index + 2

    def heapify_up(self, index):
        """Heapify the tree from bottom up starting from the given index."""
        while index != 0 and self.heap[self.parent(index)] > self.heap[index]:
            self.heap[index], self.heap[self.parent(index)] = self.heap[self.parent(index)], self.heap[index]
            index = self.parent(index)

    def heapify_down(self, index):
        """Heapify the tree from top down starting from the given index."""
        smallest = index
        l = self.left_child(index)
        r = self.right_child(index)

        if l < len(self.heap) and self.heap[l] < self.heap[smallest]:
            smallest = l
        if r < len(self.heap) and self.heap[r] < self.heap[smallest]:
            smallest = r
        if smallest != index:
            self.heap[index], self.heap[smallest] = self.heap[smallest], self.heap[index]
            self.heapify_down(smallest)

    def insert(self, element):
        """Insert an element into the heap."""
        self.heap.append(element)
        self.heapify_up(len(self.heap) - 1)

    def extract_min(self):
        """Extract and return the minimum element from the heap."""
        if not self.heap:
            return None

        if len(self.heap) == 1:
            return self.heap.pop()

        root = self.heap[0]
        self.heap[0] = self.heap.pop()
        self.heapify_down(0)
        return root

    def heapify(self, arr):
        """Build a min-heap from the given array."""
        self.heap = arr
        for i in range((len(arr) // 2) - 1, -1, -1):
            self.heapify_down(i)
