def parse_performance_metrics(input_string):
    """
    Parses a string of performance metrics into a dictionary.

    Args:
    input_string (str): A string containing performance metrics in the format "key=value" separated by commas.

    Returns:
    dict: A dictionary with component names as keys and their performance metrics as float values.
    """
    if not input_string:
        return {}

    performance_metrics = {}
    pairs = input_string.split(',')

    for pair in pairs:
        pair = pair.strip()
        if pair.count('=') == 1:
            key, value = pair.split('=')
            key = key.strip()
            try:
                value = float(value.strip())
                performance_metrics[key] = value
            except ValueError:
                continue

    return performance_metrics
